import React, { useState } from 'react';

import { Reorder, useDragControls } from 'framer-motion';

import { Box, Flex, HStack, Text, IconButton } from '@chakra-ui/react';
import { Tooltip } from './ui/tooltip';
import { useColorMode } from './ui/color-mode';
import { LuTrash, LuGripVertical } from 'react-icons/lu';
import { useCurrentDate } from '../hooks/useCurrentDate';
import { useAppContext } from '../context/AppProvider';
import { useTransactionsContext } from '../context/TransactionsProvider';

const TransactionsListItem = ({ transaction, onDelete }) => {
  const [itemTooltipIsVisible, setItemTooltipIsVisible] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const controls = useDragControls(); // Hook is called here in the subcomponent
  const currentDate = useCurrentDate();

  const { setLastOperationDate } = useAppContext();
  const { transactions } = useTransactionsContext();

  const isDraggable = transactions.length > 1;

  const { colorMode } = useColorMode();

  // Dynamically set cursor style based on transaction count and dragging state
  const cursorStyle = isDraggable ? (isDragging ? 'grabbing' : 'grab') : 'not-allowed';

  const dragVariants = {
    initial: { zIndex: 0, opacity: '100%' },
    dragging: { zIndex: 1, opacity: '25%' },
  };

  return (
    <Flex
      as={Reorder.Item}
      dragListener={false}
      dragControls={controls}
      alignItems='center'
      justifyContent='space-between'
      gap={4}
      key={transaction.id}
      value={transaction}
      variants={dragVariants}
      initial='initial'
      whileDrag='dragging'
      position='relative'
      style={{ touchAction: 'none' }}
      onDragEnd={() => {
        setIsDragging(false);
        setLastOperationDate(currentDate);
      }}
      onDragStart={() => setIsDragging(true)}>
      <HStack gap={4}>
        <Box className='reorder-handle' onPointerDown={(e) => isDraggable && controls.start(e)} style={{ cursor: cursorStyle }} color='lightMode.border' _dark={{ color: 'darkMode.border' }}>
          <LuGripVertical />
        </Box>
        <Box>
          <Text fontSize='lg' fontWeight='700'>
            {transaction.value.toFixed(2)} PLN
          </Text>
          <Text fontSize='sm' color='lightMode.bgAccent' _dark={{ color: 'darkMode.bgAccent' }} fontWeight='600'>
            {transaction.cashback.toFixed(2)} PLN
          </Text>
          {transaction.date && (
            <Text fontSize='xs' color='lightMode.textSecondary' _dark={{ color: 'darkMode.textSecondary' }} fontWeight='400' opacity='50%'>
              Data transakcji: {transaction.date}
            </Text>
          )}
        </Box>
      </HStack>
      <Flex gap={4} align='stretch'>
        <Tooltip content='Usuń transakcję' open={itemTooltipIsVisible} positioning={{ placement: 'left-end' }}>
          <IconButton
            color={colorMode === 'light' ? 'white' : '#111d1d'}
            bg={colorMode === 'light' ? 'red.500' : 'red.200'}
            aria-label='Usuń transakcję'
            size='xs'
            onClick={() => {
              onDelete(transaction);
              setItemTooltipIsVisible(false);
            }}
            onMouseEnter={() => setItemTooltipIsVisible(true)}
            onMouseLeave={() => setItemTooltipIsVisible(false)}>
            <LuTrash />
          </IconButton>
        </Tooltip>
      </Flex>
    </Flex>
  );
};

export default TransactionsListItem;
