import React, { useState } from 'react';

import { IconButton } from '@chakra-ui/react';
import { useColorMode } from './ui/color-mode';

import { Tooltip } from './ui/tooltip';
import { LuMoon, LuSun } from 'react-icons/lu';

const DarkModeToggle = () => {
  const { colorMode, toggleColorMode } = useColorMode();
  const [itemTooltipIsVisible, setItemTooltipIsVisible] = useState(false);

  return (
    <Tooltip content={`Włącz tryb ${colorMode === 'light' ? 'ciemny' : 'jasny'}`} open={itemTooltipIsVisible} positioning={{ placement: 'bottom-end' }}>
      <IconButton
        bg='lightMode.iconButtonBg'
        _dark={{ bg: 'darkMode.iconButtonBg', color: 'darkMode.bgAccent', _hover: { bg: 'darkMode.bgAccent', color: 'darkMode.iconButtonBg' } }}
        color='lightMode.bgAccent'
        _hover={{
          bg: 'lightMode.bgAccent',
          color: 'lightMode.iconButtonBg',
        }}
        position='absolute'
        top={6}
        right={6}
        left='auto'
        size='sm'
        aria-label={`Włącz tryb ${colorMode === 'light' ? 'ciemny' : 'jasny'}`}
        onClick={() => {
          toggleColorMode();
          setItemTooltipIsVisible(false);
        }}
        onMouseEnter={() => setItemTooltipIsVisible(true)}
        onMouseLeave={() => setItemTooltipIsVisible(false)}>
        {colorMode === 'light' ? <LuMoon /> : <LuSun />}
      </IconButton>
    </Tooltip>
  );
};
export default DarkModeToggle;
