import React, { useState } from 'react';

import { Flex, Heading, IconButton } from '@chakra-ui/react';
import { Tooltip } from './ui/tooltip';
import { LuRefreshCw } from 'react-icons/lu';

import { useTransactionsContext } from '../context/TransactionsProvider';

const TransactionsHeading = () => {
  const { transactions, openDialog } = useTransactionsContext();
  const [itemTooltipIsVisible, setItemTooltipIsVisible] = useState(false);

  // Show confirmation dialog to clear all transactions
  const handleClear = () => {
    openDialog();
  };

  return (
    <Flex alignItems='center' justifyContent='space-between'>
      <Heading size='md'>Twoje transakcje</Heading>
      <Tooltip content='Wyczyść listę transakcji' open={itemTooltipIsVisible}>
        <IconButton
          bg='lightMode.iconButtonBg'
          _dark={{ bg: 'darkMode.iconButtonBg', color: 'darkMode.bgAccent', _hover: { bg: 'darkMode.bgAccent', color: 'darkMode.iconButtonBg' } }}
          color='lightMode.bgAccent'
          _hover={{ bg: 'lightMode.bgAccent', color: 'lightMode.iconButtonBg' }}
          aria-label='Wyczyść listę transakcji'
          size='sm'
          onClick={() => {
            handleClear();
            setItemTooltipIsVisible(false);
          }}
          onMouseEnter={() => setItemTooltipIsVisible(true)}
          onMouseLeave={() => setItemTooltipIsVisible(false)}
          disabled={transactions.length === 0}>
          <LuRefreshCw />
        </IconButton>
      </Tooltip>
    </Flex>
  );
};
export default TransactionsHeading;
