import React, { useEffect, useState } from 'react';

import { Box, Button, IconButton, Input } from '@chakra-ui/react';
import { InputGroup } from './ui/input-group';
import { Field } from './ui/field';
import { Tooltip } from './ui/tooltip';
import { LuCircleX } from 'react-icons/lu';
import { NumberInputField, NumberInputLabel, NumberInputRoot } from './ui/number-input';

import { CASHBACK_PERCENTAGE_VALUE } from '../constants';
import { useCalculatorContext } from '../context/CalculatorProvider';
import { useAppContext } from '../context/AppProvider';
import { useCurrentDate } from '../hooks/useCurrentDate';

const CalculatorForm = () => {
  const { setTransactions, transactions, accumulatedCashback, setAccumulatedCashback, errorAlertRef, remainingSpendLimit, setRemainingSpendLimit, transactionAmount, setTransactionAmount, formError, setFormError } = useCalculatorContext();
  const { showToast, isSmallScreen, inputRef, setLastOperationDate } = useAppContext();
  const currentDate = useCurrentDate();

  const [showClear, setShowClear] = useState(false);
  const [itemTooltipIsVisible, setItemTooltipIsVisible] = useState(false);

  // Function to add a new transaction
  const addTransaction = () => {
    const transactionInputValue = parseFloat(transactionAmount);

    // Validate transaction amount
    if (!transactionAmount || isNaN(transactionInputValue) || transactionInputValue <= 0) {
      setFormError(true);
      setLastOperationDate(currentDate);
      return;
    }

    // Calculate cashback for the transaction
    let calculatedCashback = parseFloat((transactionInputValue * CASHBACK_PERCENTAGE_VALUE).toFixed(2));
    let parsedTransactionValue = parseFloat(transactionInputValue.toFixed(2));

    // Update transactions state with the new transaction
    setTransactions([
      ...transactions,
      {
        id: Date.now(),
        value: parsedTransactionValue,
        cashback: calculatedCashback,
        date: currentDate(),
      },
    ]);

    // Update accumulated cashback and remaining spend limit
    let updatedAccumulatedCashback = parseFloat((accumulatedCashback + calculatedCashback).toFixed(2));
    setAccumulatedCashback(updatedAccumulatedCashback);

    let updatedRemainingSpendLimit = parseFloat((remainingSpendLimit - transactionInputValue).toFixed(2));
    setRemainingSpendLimit(updatedRemainingSpendLimit);

    // Show toast notification for added transaction
    showToast('item-added-success', 'Transakcja dodana', 'info');

    // Update operation date
    setLastOperationDate(currentDate);

    // Clear transaction input field
    setTransactionAmount('');

    // Refocus input field if not on small screen
    if (!isSmallScreen && inputRef.current) {
      inputRef.current.focus();
    }
  };

  // Handle Enter key press to add transaction
  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      addTransaction();
    }
    if (parseFloat(e.valueAsNumber) === 0) {
      inputRef.current.value = '';
      setFormError(true);
    }
  };

  const handleOnChange = (e) => {
    setTransactionAmount(e.valueAsNumber);
    setFormError(false);
  };

  const handleValueClearOnClick = () => {
    setTransactionAmount('');
    setFormError(false);
    setShowClear(false);
  };

  useEffect(() => {
    if (transactionAmount > 0 && !formError) {
      setShowClear(true);
    }
    return () => {
      setShowClear(false);
    };
  }, [transactionAmount, formError]);

  // Scroll to error alert on small screens if there's an input error
  useEffect(() => {
    if (isSmallScreen && errorAlertRef.current) {
      errorAlertRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }
  }, [formError, isSmallScreen, errorAlertRef]);

  // Reset input error when transactions change
  useEffect(() => {
    if (transactions.length > 0) {
      setFormError(false);
    }
  }, [transactions, setFormError]);

  return (
    <>
      <Field label='Wartość transakcji' id='transaction-value' my='3'>
        <InputGroup
          flex='1'
          width='100%'
          endElement={
            showClear && (
              <Tooltip content='Wyczyść pole' open={itemTooltipIsVisible} positioning={{ placement: 'top-center' }}>
                <IconButton
                  aria-label='Wyczyść'
                  size='xs'
                  bg='lightMode.iconButtonBg'
                  _dark={{
                    bg: 'darkMode.iconButtonBg',
                    color: 'darkMode.bgAccent',
                    _hover: {
                      bg: 'darkMode.bgAccent',
                      color: 'darkMode.iconButtonBg',
                    },
                  }}
                  color='lightMode.bgAccent'
                  _hover={{ bg: 'lightMode.bgAccent', color: 'lightMode.iconButtonBg' }}
                  onClick={() => {
                    handleValueClearOnClick();
                    setItemTooltipIsVisible(false);
                  }}
                  onMouseEnter={() => setItemTooltipIsVisible(true)}
                  onMouseLeave={() => setItemTooltipIsVisible(false)}>
                  <LuCircleX size='xs' />
                </IconButton>
              </Tooltip>
            )
          }>
          <NumberInputRoot
            width='100%'
            value={transactionAmount}
            onValueChange={(e) => handleOnChange(e)}
            onKeyDown={handleKeyDown}
            step='0.01'
            ref={inputRef}
            borderColor='lightMode.inputBorder'
            _dark={{ borderColor: 'darkMode.inputBorder' }}
            placeholder={'Wpisz wartość transakcji, np. 1.50'}
            invalid={formError}>
            <NumberInputLabel />
            <NumberInputField />
          </NumberInputRoot>
          {/* <Input
            type='number'
            value={transactionAmount || ''}
            step='0.01'
            onChange={handleOnChange}
            onBlur={() => setTransactionAmount(parseFloat(transactionAmount).toFixed(2))}
            onKeyDown={handleKeyDown}
            // TODO: Refactor
            invalid={formError}
            ref={inputRef}
            borderColor='lightMode.inputBorder'
            _dark={{ borderColor: 'darkMode.inputBorder' }}
            placeholder={'Wpisz wartość transakcji, np. 1.50'}
          /> */}
        </InputGroup>
      </Field>
      <Button
        bg='lightMode.bgAccent'
        color='white'
        _hover={{ bg: 'lightMode.bgAccentHover', _disabled: { bg: 'lightMode.bgAccent' } }}
        _dark={{ bg: 'darkMode.bgAccent', color: '#0C1918', _hover: { bg: 'darkMode.bgAccentHover', _disabled: { bg: 'darkMode.bgAccent' } } }}
        width='100%'
        onClick={addTransaction}
        disabled={!transactionAmount || isNaN(Number(transactionAmount)) || formError}>
        Dodaj transakcję
      </Button>
    </>
  );
};
export default CalculatorForm;
