import React from 'react';

import { Button } from './ui/button';
import { DialogActionTrigger, DialogBody, DialogCloseTrigger, DialogContent, DialogFooter, DialogHeader, DialogRoot, DialogTitle } from './ui/dialog';

import { useAlertsContext } from '../context/AlertsProvider';
import { useAppContext } from '../context/AppProvider';

const AlertsClearAllTransactions = () => {
  const { isOpen, closeDialog } = useAlertsContext();
  const { clearAllTransactions } = useAppContext();

  return (
    <DialogRoot open={isOpen} onClose={closeDialog} placement='center'>
      <DialogContent margin={{ base: '0 1rem', lg: '' }} bg='white' _dark={{ bg: 'darkMode.bgWrapperPrimary' }}>
        <DialogHeader>
          <DialogTitle>Wyczyścić listę transakcji?</DialogTitle>
        </DialogHeader>
        <DialogBody fontWeight='600' color='lightMode.textSecondary' _dark={{ color: 'darkMode.textSecondary' }}>
          Czy na pewno chcesz wyczyścić listę transakcji?
        </DialogBody>
        <DialogFooter>
          <DialogActionTrigger asChild>
            <Button onClick={closeDialog}>Anuluj</Button>
          </DialogActionTrigger>
          <Button onClick={clearAllTransactions} colorPalette='red'>
            Usuń
          </Button>
        </DialogFooter>
        <DialogCloseTrigger onClick={closeDialog} />
      </DialogContent>
    </DialogRoot>
  );
};
export default AlertsClearAllTransactions;
